python3 -c "
import json
# Read metrics and extract key training signals at each step
steps = []
with open('/user/user1/harbor-runs/ac6993830155/workspace/outputs/metrics.jsonl') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            rec = json.loads(line)
        except:
            continue
        step = rec.get('step')
        data = rec.get('data', {})
        row = {'step': step}
        # training reward
        for k in ['actor/reward_mean', 'actor/reward_std', 'actor/ppo_kl', 'actor/pg_clipfrac', 'actor/luspo_token_loss', 'actor/lr']:
            if k in data:
                row[k] = data[k]
        # val core aime scores
        for k in ['val-core/aime24/acc/mean@32', 'val-core/aime25/acc/mean@32', 'val-aux/aime24/reward/mean@32', 'val-aux/aime25/reward/mean@32']:
            if k in data:
                row[k] = data[k]
        steps.append(row)

# Print key steps: first, every 30th, and last
for i in [0] + list(range(10, len(steps), 10)) + [len(steps)-1]:
    if i < len(steps):
        print(json.dumps(steps[i]))
"

